mapper.update:
update bm_execute_record_copy set is_discard = true
where
product_plan_id = #{productPlanId}
and record_item_id = #{recordItemId}
and is_reuse = #{reuse}
and version = #{copyVersion}
and is_discard = false

    and procedure_step_id = #{procedureStepId}

mapper.select:
select max(version)
from bm_execute_record_copy
where
    product_plan_id = #{productPlanId}
    and record_item_id = #{recordItemId}
    and is_reuse = #{reuse}

    and procedure_step_id = #{procedureStepId}

select distinct
    version,
    is_discard as discard,
    procedure_change_number,
    process_change_number
from bm_execute_record_copy
where
product_plan_id = #{productPlanId}

    and record_item_id = #{recordItemId}

and is_reuse = #{reuse}

    and procedure_step_id = #{procedureStepId}


    and procedure_change_number =#{procedureChangeNumber}


    and process_change_number =#{processChangeNumber}
